"""Netact"""
from robot.api import logger
from robot.libraries.BuiltIn import BuiltIn
from taf.ul.trs_e2e_fw.lib.utils.config_utils import get_config_variable
from taf.ul.trs_e2e_fw.lib.remote_connection.controller import Controller


class NetAct(object):
    """Netact"""
    def __init__(self):
        self.controller = Controller()
        self.alias = "netact"

    def perform_operation(self, netact_section, operation_section):
        """Perfrom Operation"""
        netact_details = self._get_details_from_testcase_config(operation_section)
        status = self._execute_netact_command(netact_section, netact_details)
        self._verify_execution_on_remote_location(status)

    def _get_details_from_testcase_config(self, operation_section):
        netact_details = get_config_variable(["netact", operation_section])
        logger.debug("Netact operation details :: {0}".format(str(netact_details)))
        return netact_details

    def _execute_netact_command(self, netact_section, netact_details):
        netact_string = self._get_netact_command_string(netact_details)
        status = self._execute_command_on_remote_location(netact_section, netact_string)
        return status

    def _get_netact_command_string(self, netact_details):
        command_string = "sh raccli.sh "
        for option in self._get_option_list_for_netact_operation(netact_details.get("operation")):
            command_string += " -{0} {1}".format(str(option), str(netact_details["options"].get(option.lower(), "")))
        logger.debug("Netact command string :: {0}".format(command_string))
        return command_string

    def _execute_command_on_remote_location(self, netact_section, netact_string):
        self.controller.create_session_with_host(netact_section, self.alias)
        output, status = self.controller.execute_command_on_host(netact_string, True, self.alias, False)
        self.controller.close_session_with_host(self.alias)
        return status

    def _verify_execution_on_remote_location(self, status):
        if not status:
            BuiltIn().fail("FAIL :: NetAct (raccli.sh) execution failed.")
        else:
            logger.info("PASS :: Netact execution completed succesfully")

    def _get_option_list_for_netact_operation(self, operation):
        operation_dict = {
            "cm_upload": ["op Upload", "DN", "btsContentInUse", "v"],
            "delta_commissioning": ["op Provision", "opsName", "planName", "createBackupPlan", "-backupPlanName", "v"]
        }
        return operation_dict[operation]


def perform_netact_operation(netact_section, operation_section):
    """

    -*Perform Netact Operation*_ : Performs operations related to Netact.

    *Usage*:

    Perform Netact Operation    <netact_section>    <operation_section>

    *Argument Details*:

    | *arguments* | *comment* |
    | *netact_section* | section in test_line_config json file which contains credentials of
        netact system |
    | *operation_section* | section in testcase_config json file which contains details of
        netact operation |

    *Example*:

    | *keyword* | *netact_section* | *operation_section* |
    | *Perform Netact Operation* | *netact* | *operation1* |

    *Note*:

    testcase config must contain the details regarding the operation in the following format.

    "netact":
        {
            operation1:{
                            "operation":"cm_upload",
                            "options":{
                                        "DN": "PLMN-PLMN/RNC-190/WBTS-967",
                                        "btsContentInUse": "true"
                                    }
                        }
        }

    Here "netact" is a fixed section name in json file. operation1 (operation_section) is a user
        defined section name.

    """
    NetAct().perform_operation(netact_section=netact_section, operation_section=operation_section)
